window.CARDS=window.CARDS||{};CARDS["people-amasawa-ichika"]=[{"i":"sc-amasawa-ichika-y2v1-p120-1","v":"y2v1","y":2,"o":16,"k":"","w":"horikita-suzune sudou-ken ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika ch 3  meeting horikita and sudo approaches horikita on the stairs and offers to partner  says she likes strong  powerful guys  sets a cooking test for ayanokoji  agrees to meet tomorrow after school at keyaki mall  negotiates with her  conditionally offers to partner with him  sets him a cooking test","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v1-p120-1\"><h3><span class=\"ttl\">Ch.3: Meeting Horikita and Sudō<\/span><span class=\"meta\">Y2V1 · p.120–141<\/span><\/h3><p class=\"setup\">Approaches Horikita on the stairs and offers to partner. Says she likes strong, powerful guys. Sets a cooking test for Ayanokōji. Agrees to meet tomorrow after school at Keyaki Mall.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates with her.<span class=\"pg\">p.120–141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Conditionally offers to partner with him.<span class=\"pg\">p.123–141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Sets him a cooking test.<span class=\"pg\">p.129–141<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v1-p120-2\">→ After: Ch.4: Cooking test<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v1-p120-2","v":"y2v1","y":2,"o":16,"k":"","w":"horikita-suzune sudou-ken ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika ch 4  cooking test approaches horikita on the stairs  says she likes strong  powerful guys  sets a cooking test for ayanokoji  shops with ayanokoji for ingredients and utensils  tasks him with making tom yum goong  judges the dish just barely good enough  agrees to partner with sudo  declines to act as intermediary for class 1 a  negotiates with her  agrees to partner with him  sets and judges his cooking test","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v1-p120-2\"><h3><span class=\"ttl\">Ch.4: Cooking test<\/span><span class=\"meta\">Y2V1 · p.120–189<\/span><\/h3><p class=\"setup\">Approaches Horikita on the stairs. Says she likes strong, powerful guys. Sets a cooking test for Ayanokōji. Shops with Ayanokōji for ingredients and utensils. Tasks him with making tom yum goong. Judges the dish just barely good enough. Agrees to partner with Sudō. Declines to act as intermediary for Class 1-A.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates with her.<span class=\"pg\">p.120–141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Agrees to partner with him.<span class=\"pg\">p.123–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Sets and judges his cooking test.<span class=\"pg\">p.129–189<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v1-p120-1\">← Before: Ch.3: Meeting Horikita and Sudō<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v1-p176-1\">→ After: Amasawa&#x27;s cooking test; agreeing to partner with Sudō<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v1-p176-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"ayanokouji-kiyotaka sudou-ken amasawa-ichika","q":"amasawa ichika amasawa s cooking test  agreeing to partner with sudo comes to ayanokoji s dorm room with groceries  treating the visit like a fun outing  sets strict rules for the cooking test   anyway  i m super picky about taste  if it s not yummy enough  the deal s off  okay   oh  looking up anything on your phone is against the rules  okay   pardon the intru sion  wow  you ve really got it all nice and tidy  huh  it s like  super clean too   you scaaared   sounds wonderful then  cuz in my book  a good cook is somebody who knows the recipe by heart   the dish you re gonna make is  tom yum goong   wow  how amazing  you re doing perfectly  the way you handle that knife gets full marks from me   i do though  it s just like  i thought you might figure out what the dish was if we got cilantro   yeah  i guess it was just barely good enough  it wasn t  like  super delicious or anything  but i think it tasted good enough for me to wanna try it again   while i can t exactly say you passed  it s true that you can cook   i ll pair up with sudo senpai  outta respect for your efforts   so rry  but i don t think that s possible   i m not the type to sugarcoat my words  cheerful  playful and sharp   deliberately omits cilantro to prevent him identifying the dish  checks his technique closely  eats every bite  and meticulously cleans the kitchen  used to helping her mother  refuses to be an intermediary because she isn t close to her class 1 a classmates  tests his cooking  agrees to partner with sudo out of respect  and declines his intermediary request  agrees to partner with him and submits the application","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v1-p176-1\"><h3><span class=\"ttl\">Amasawa&#x27;s cooking test; agreeing to partner with Sudō<\/span><span class=\"meta\">Y2V1 · p.176–189<\/span><\/h3><p class=\"setup\">Comes to Ayanokōji&#x27;s dorm room with groceries, treating the visit like a fun outing; sets strict rules for the cooking test.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Anyway, I&#x27;m super picky about taste~ If it&#x27;s not yummy enough, the deal&#x27;s off, okay?&quot;<span class=\"pg\">p.176<\/span><\/li><li class=\"q spoken\">&quot;Oh, looking up anything on your phone is against the rules, okay~?&quot;<span class=\"pg\">p.176<\/span><\/li><li class=\"q spoken\">&quot;Pardon the intru~sion. Wow, you&#x27;ve really got it all nice and tidy, huh? It&#x27;s like, super clean too~&quot;<span class=\"pg\">p.177<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You scaaared~?&quot;<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Sounds wonderful then. Cuz in my book, a good cook is somebody who knows the recipe by heart.&quot;<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The dish you&#x27;re gonna make is… tom yum goong!&quot;<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Wow~ How amazing! You&#x27;re doing perfectly! The way you handle that knife gets full marks from me!&quot;<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I do though? It&#x27;s just like, I thought you might figure out what the dish was if we got cilantro.&quot;<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah, I guess it was just barely good enough. It wasn&#x27;t, like, super delicious or anything, but I think it tasted good enough for me to wanna try it again.&quot;<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;While I can&#x27;t exactly say you passed, it&#x27;s true that you can cook.&quot;<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ll pair up with Sudō-senpai, outta respect for your efforts.&quot;<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So~rry, but I don&#x27;t think that&#x27;s possible.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m not the type to sugarcoat my words.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cheerful, playful and sharp — deliberately omits cilantro to prevent him identifying the dish, checks his technique closely, eats every bite, and meticulously cleans the kitchen (used to helping her mother); refuses to be an intermediary because she isn&#x27;t close to her Class 1-A classmates.<span class=\"pg\">p.176–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tests his cooking; agrees to partner with Sudō out of respect, and declines his intermediary request.<span class=\"pg\">p.176–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Agrees to partner with him and submits the application.<span class=\"pg\">p.187–188<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v1-p120-2\">← Before: Ch.4: Cooking test<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v1-p245-1\">→ After: Ch.5: Hair tie visit<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v1-p245-1","v":"y2v1","y":2,"o":16,"k":"","w":"ayanokouji-kiyotaka karuizawa-kei amasawa-ichika","q":"amasawa ichika ch 5  hair tie visit visits ayanokoji s room looking for a hair tie  meets karuizawa in his room  proposes kei join future cooking sessions  visits his room  meets her","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v1-p245-1\"><h3><span class=\"ttl\">Ch.5: Hair tie visit<\/span><span class=\"meta\">Y2V1 · p.245–254<\/span><\/h3><p class=\"setup\">Visits Ayanokōji’s room looking for a hair tie. Meets Karuizawa in his room. Proposes Kei join future cooking sessions.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Visits his room.<span class=\"pg\">p.245–254<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Meets her.<span class=\"pg\">p.250–254<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v1-p176-1\">← Before: Amasawa&#x27;s cooking test; agreeing to partner with Sudō<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v1-p245-2\">→ After: Epilogue: Hair tie visit<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v1-p245-2","v":"y2v1","y":2,"o":16,"k":"","w":"ayanokouji-kiyotaka karuizawa-kei amasawa-ichika","q":"amasawa ichika epilogue  hair tie visit visits ayanokoji s room looking for a hair tie  meets karuizawa in his room  proposes kei join future cooking sessions  visits his room  meets her","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v1-p245-2\"><h3><span class=\"ttl\">Epilogue: Hair tie visit<\/span><span class=\"meta\">Y2V1 · p.245–254<\/span><\/h3><p class=\"setup\">Visits Ayanokōji’s room looking for a hair tie. Meets Karuizawa in his room. Proposes Kei join future cooking sessions.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Visits his room.<span class=\"pg\">p.245–254<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Meets her.<span class=\"pg\">p.250–254<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v1-p245-1\">← Before: Ch.5: Hair tie visit<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v2-p6-1","v":"y2v2","y":2,"o":17,"k":"","w":"ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika amasawa  white room prologue  her pov  in her own voice she explains she is a fifth generation white room student  that she has always been compared to the fourth generation  god  ayanokoji kiyotaka and found wanting  and that she worships only hatred  not him  she watched him through a visiting room and shivered at his figure  this is amasawa s interior monologue  her pov  no spoken line is quoted  driven by hatred rather than worship   she refuses to revere ayanokoji and treats him as her enemy  the obstacle to her being recognized as the white room s success story  to prove ayanokoji is not number one and to be recognized by the organization as the true success  the opportunity comes now that he has refused to return to the restarted white room  the fourth generation  god  she has been measured against her whole life  she has resolved to bury him","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v2-p6-1\"><h3><span class=\"ttl\">Amasawa: White Room prologue (her POV)<\/span><span class=\"meta\">Y2V2 · p.6–10<\/span><\/h3><p class=\"setup\">In her own voice she explains she is a fifth-generation White Room student, that she has always been compared to the fourth-generation &quot;god&quot; Ayanokōji Kiyotaka and found wanting, and that she worships only hatred, not him; she watched him through a visiting room and shivered at his figure.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> This is Amasawa&#x27;s interior monologue (her POV); no spoken line is quoted.<span class=\"pg\">p.6–10<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Driven by hatred rather than worship — she refuses to revere Ayanokōji and treats him as her enemy, the obstacle to her being recognized as the White Room&#x27;s success story.<span class=\"pg\">p.6–10<\/span><\/li><li><span class=\"mlabel\">Goal<\/span> To prove Ayanokōji is not number one and to be recognized by the organization as the true success; the opportunity comes now that he has refused to return to the restarted White Room.<span class=\"pg\">p.6–10<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The fourth-generation &quot;god&quot; she has been measured against her whole life; she has resolved to bury him.<span class=\"pg\">p.6–10<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v2-p92-1\">→ After: Amasawa forces her way in and teases Kei<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v2-p92-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"ayanokouji-kiyotaka karuizawa-kei amasawa-ichika","q":"amasawa ichika amasawa forces her way in and teases kei she arrives at ayanokoji s door with ingredients  demands entry  and reveals she watched kei enter his room   senpai  you look like you are alone anyway  so cook for me   did you lie to me because you didn t want me to come into the room  she enters  teases them about sex  and gives kei a contraceptive as a  gift  and apology for her role in the hosen attack   i thought you would have an illicit sexual relationship for sure  i mean having sex   take this as a gift from me  no  take it as an apology   i m not ayanokouji senpai s enemy  playful  shameless  and calculating   she uses leverage to force entry and gathers intelligence  she pressures him and he concedes  she teases kei and threatens exposure","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v2-p92-1\"><h3><span class=\"ttl\">Amasawa forces her way in and teases Kei<\/span><span class=\"meta\">Y2V2 · p.92–108<\/span><\/h3><p class=\"setup\">She arrives at Ayanokōji&#x27;s door with ingredients, demands entry, and reveals she watched Kei enter his room. She enters, teases them about sex, and gives Kei a contraceptive as a &quot;gift&quot; and apology for her role in the Hōsen attack.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Senpai, you look like you are alone anyway, so cook for me.&quot;<span class=\"pg\">p.92<\/span><\/li><li class=\"q spoken\">&quot;Did you lie to me because you didn&#x27;t want me to come into the room?&quot;<span class=\"pg\">p.97<\/span><\/li><li class=\"q spoken\">&quot;I thought you would have an illicit sexual relationship for sure… I mean having sex.&quot;<span class=\"pg\">p.100<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Take this as a gift from me… No, take it as an apology.&quot;<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m not Ayanokouji-senpai&#x27;s enemy.&quot;<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful, shameless, and calculating — she uses leverage to force entry and gathers intelligence.<span class=\"pg\">p.92–108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She pressures him and he concedes.<span class=\"pg\">p.92–108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> She teases Kei and threatens exposure.<span class=\"pg\">p.98–108<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v2-p6-1\">← Before: Amasawa: White Room prologue (her POV)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v2-p100-1\">→ After: Amasawa&#x27;s visit: the condom &quot;gift&quot; and her hints<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v2-p100-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"ayanokouji-kiyotaka karuizawa-kei amasawa-ichika","q":"amasawa ichika amasawa s visit  the condom  gift  and her hints visits ayanokoji s room  where he and karuizawa were studying  teasing them about an illicit sexual relationship  then places a contraceptive on the table as a supposed gift and apology   i thought you would have an illicit sexual relationship for sure  i mean having sex   take this as a gift from me  no  take it as an apology   quit playing dumb  the wound on your hand  i had a part in that right  because i teamed up with housen   i m not ayanokouji senpai s enemy   ayanokouji senpai  haven t you told your girlfriend about that  then what about the 20 million point bounty   because senpai suddenly had a bounty for his head  and i thought that it was a pity that you would be expelled without even knowing the situation   go make a cup of coffee for amasawa    ayanokoji  she piles on requests  don t put garbage or sewage into my coffee because you don t like me   let s see  hmmm  what was the convention adopted at the general conference of the united nations educational  scientific and cultural organization in 1972    she correctly writes  world heritage convention  playful  shameless and razor sharp   probes the couple mercilessly  openly admits her role in the knife plot  claims she isn t his enemy  and reveals she left a deliberate  trace   her instant choice of the knife at the store  so ayanokoji could defend himself  answers a college level question with ease and has karuizawa make her coffee purely to tease her  then leaves without drinking it  admits helping hosen  claims not to be his enemy  and leaves clues that raise ayanokoji s vigilance that she could be the white room student  teases her mercilessly about the relationship  has her make coffee  with milk and sugar  and writes in her notebook  karuizawa shows undisguised disgust","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v2-p100-1\"><h3><span class=\"ttl\">Amasawa&#x27;s visit: the condom &quot;gift&quot; and her hints<\/span><span class=\"meta\">Y2V2 · p.100–107<\/span><\/h3><p class=\"setup\">Visits Ayanokōji&#x27;s room (where he and Karuizawa were studying), teasing them about an illicit sexual relationship, then places a contraceptive on the table as a supposed gift and apology.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I thought you would have an illicit sexual relationship for sure… I mean having sex.&quot;<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">&quot;Take this as a gift from me… No, take it as an apology.&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\">&quot;Quit playing dumb, the wound on your hand, I had a part in that right? Because I teamed up with Housen.&quot;<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m not Ayanokouji-senpai&#x27;s enemy.&quot;<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ayanokouji-senpai, haven&#x27;t you told your girlfriend about that? Then what about the 20 million point bounty?&quot;<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Because senpai suddenly had a bounty for his head, and I thought that it was a pity that you would be expelled without even knowing the situation.&quot;<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Go make a cup of coffee for Amasawa.&quot; — Ayanokōji; she piles on requests<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Don&#x27;t put garbage or sewage into my coffee because you don&#x27;t like me.&quot;<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Let&#x27;s see, hmmm? What was the convention adopted at the General Conference of the United Nations Educational, Scientific and Cultural Organization in 1972?&quot; — she correctly writes &quot;World Heritage Convention&quot;<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful, shameless and razor-sharp — probes the couple mercilessly, openly admits her role in the knife plot, claims she isn&#x27;t his enemy, and reveals she left a deliberate &quot;trace&quot; (her instant choice of the knife at the store) so Ayanokōji could defend himself; answers a college-level question with ease and has Karuizawa make her coffee purely to tease her, then leaves without drinking it.<span class=\"pg\">p.100–107<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Admits helping Hōsen, claims not to be his enemy, and leaves clues that raise Ayanokōji&#x27;s vigilance that she could be the White Room student.<span class=\"pg\">p.100–107<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Teases her mercilessly about the relationship, has her make coffee (with milk and sugar), and writes in her notebook; Karuizawa shows undisguised disgust.<span class=\"pg\">p.100–107<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v2-p92-1\">← Before: Amasawa forces her way in and teases Kei<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v2-p345-1\">→ After: Short story: &quot;What is Reflected in Her Eyes&quot; — staking out Karuizawa<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v2-p345-1","v":"y2v2","y":2,"o":17,"k":"narration","w":"ayanokouji-kiyotaka karuizawa-kei nomura-shuuji amasawa-ichika","q":"amasawa ichika short story   what is reflected in her eyes    staking out karuizawa from her own pov  spends two weeks watching karuizawa  then stalks her from the dorm to ayanokoji s floor  changes into cute clothes  buys ingredients and a  small amorous box  and tails another resident through the auto lock   will he think i m cute   hmm  perfect   se npai   it s me  obsessive  playful and calculating   delights in the  hardship  of the stakeout  carefully plans her outfit and props  aims at ayanokoji s few weaknesses to get invited in  and anticipates all his ways of rejecting her  two arrows  three arrows  obsessed with him   wants him to find her cute and to be invited into his room  stalks her for two weeks to confirm the secret  date  follows him through the dorm auto lock to reach room 401","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v2-p345-1\"><h3><span class=\"ttl\">Short story: &quot;What is Reflected in Her Eyes&quot; — staking out Karuizawa<\/span><span class=\"meta\">Y2V2 · p.345–347<\/span><\/h3><p class=\"setup\">From her own POV, spends two weeks watching Karuizawa, then stalks her from the dorm to Ayanokōji&#x27;s floor, changes into cute clothes, buys ingredients and a &quot;small amorous box,&quot; and tails another resident through the auto-lock.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Will he think I&#x27;m cute?&quot;<span class=\"pg\">p.345<\/span><\/li><li class=\"q narration\">&quot;Hmm, perfect!&quot;<span class=\"pg\">p.346<\/span><\/li><li class=\"q narration\">&quot;Se~npai.&quot;<span class=\"pg\">p.347<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;It&#x27;s me!&quot;<span class=\"pg\">p.347<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Obsessive, playful and calculating — delights in the &quot;hardship&quot; of the stakeout, carefully plans her outfit and props, aims at Ayanokōji&#x27;s few weaknesses to get invited in, and anticipates all his ways of rejecting her (&quot;two arrows, three arrows&quot;).<span class=\"pg\">p.345–347<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Obsessed with him — wants him to find her cute and to be invited into his room.<span class=\"pg\">p.345–347<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Stalks her for two weeks to confirm the secret &quot;date.&quot;<span class=\"pg\">p.345–346<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">nomura-shuuji<\/b> Follows him through the dorm auto-lock to reach room 401.<span class=\"pg\">p.346<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v2-p100-1\">← Before: Amasawa&#x27;s visit: the condom &quot;gift&quot; and her hints<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v3-p309-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"kushida-kikyou ayanokouji-kiyotaka yagami-takuya amasawa-ichika","q":"amasawa ichika amasawa exposes kushida  declares ayanokoji  special  revealed as kushida s walkie talkie accomplice  records the fight on her tablet  then drags kushida away and confronts her   shh  i get you re surprised but you ve like  gotta be quiet  kushida senpai   you re a nasty  vile woman who s totally caught   don t try and hide it  kushida senpai  i can see through your every move   i m going to get dirt on ayanokoji and get him kicked outta here   i ll say it again  ayanokoji senpai is a very special person to me  i ll never allow him to get expelled by an outsider like you   your strength   admiring kushida even as she defeats her playful  cruel and perceptive   knows far more than ayanokoji about kushida s true nature and yagami s plot  taunts her about wanting to assert her  mask  and though she too wants ayanokoji expelled  refuses to let an  outsider  like kushida do it    ayanokoji senpai is a very special person to me  exposes and defeats her admires her strength even while mocking her  calls him  a very special person    protective of him against other threats  later confronts him too   he had been manipulating kushida","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v3-p309-1\"><h3><span class=\"ttl\">Amasawa exposes Kushida; declares Ayanokōji &quot;special&quot;<\/span><span class=\"meta\">Y2V3 · p.309–319<\/span><\/h3><p class=\"setup\">Revealed as Kushida&#x27;s walkie-talkie accomplice; records the fight on her tablet, then drags Kushida away and confronts her.<\/p><p class=\"with\">with <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Shh~ I get you&#x27;re surprised but you&#x27;ve like, gotta be quiet, Kushida-senpai.&quot;<span class=\"pg\">p.309<\/span><\/li><li class=\"q spoken\">&quot;You&#x27;re a nasty, vile woman who&#x27;s totally caught&quot;<span class=\"pg\">p.312<\/span><\/li><li class=\"q spoken\">&quot;Don&#x27;t try and hide it, Kushida-senpai. I can see through your every move.&quot;<span class=\"pg\">p.314<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m going to get dirt on Ayanokōji and get him kicked outta here,&quot;<span class=\"pg\">p.315<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ll say it again. Ayanokōji-senpai is a very special person to me. I&#x27;ll never allow him to get expelled by an outsider like you.&quot;<span class=\"pg\">p.315<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Your strength,&quot; —admiring Kushida even as she defeats her<span class=\"pg\">p.318<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful, cruel and perceptive — knows far more than Ayanokōji about Kushida&#x27;s true nature and Yagami&#x27;s plot, taunts her about wanting to assert her &quot;mask,&quot; and though she too wants Ayanokōji expelled, refuses to let an &quot;outsider&quot; like Kushida do it — &quot;Ayanokōji-senpai is a very special person to me.&quot;<span class=\"pg\">p.309–319<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Exposes and defeats her;admires her strength even while mocking her.<span class=\"pg\">p.309–319<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Calls him &quot;a very special person&quot; — protective of him against other threats.<span class=\"pg\">p.315<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Later confronts him too — he had been manipulating Kushida.<span class=\"pg\">p.322<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p5-1","v":"y2v4","y":2,"o":19,"k":"narration","w":"ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika prologue  amasawa s monologue on the white room in her own monologue  reveals she is an ivf  test tube  baby brought into the white room  with no knowledge of her parents   i am one of those born from that very process  a human brought about through in vitro fertilization   my existence runs in direct conflict with that of the white room   i personally concluded long ago that it s impossible to homogenize intellect  personality  and ethics   wouldn t that be like  you know  kinda pathetic  wouldn t you want to live more freely   ayanokoji kiyotaka  the being whose preeminent success stood out from the rest of the white room   however  i m sorry senpai  i really want to take your side  but that s just not how fate is going to play out   as one of your faithful admirers  i ll be looking on from a distance once  that time  finally comes  proud of being different  secretly questions the white room s purpose  it seeks to prove ability comes from environment  not genetics   her existence refutes it  and admires ayanokoji from afar  resolved not to devote her life to the facility s ideals  hints she has aligned with people she s known much longer  not ayanokoji  despite admiring him  she idolizes him but says fate prevents her from taking his side","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p5-1\"><h3><span class=\"ttl\">Prologue: Amasawa&#x27;s monologue on the White Room<\/span><span class=\"meta\">Y2V4 · p.5–7<\/span><\/h3><p class=\"setup\">In her own monologue, reveals she is an IVF (&quot;test-tube&quot;) baby brought into the White Room, with no knowledge of her parents.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;I am one of those born from that very process. A human brought about through in vitro fertilization.&quot;<span class=\"pg\">p.5<\/span><\/li><li class=\"q narration\">&quot;my existence runs in direct conflict with that of the White Room.&quot;<span class=\"pg\">p.5<\/span><\/li><li class=\"q narration\">&quot;I personally concluded long ago that it&#x27;s impossible to homogenize intellect, personality, and ethics.&quot;<span class=\"pg\">p.6<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Wouldn&#x27;t that be like, you know, kinda pathetic? Wouldn&#x27;t you want to live more freely?&quot;<span class=\"pg\">p.6<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Ayanokōji Kiyotaka. The being whose preeminent success stood out from the rest of the White Room.&quot;<span class=\"pg\">p.6<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;However, I&#x27;m sorry Senpai. I really want to take your side, but that&#x27;s just not how fate is going to play out.&quot;<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;As one of your faithful admirers, I&#x27;ll be looking on from a distance once &#x27;that time&#x27; finally comes.&quot;<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Proud of being different, secretly questions the White Room&#x27;s purpose (it seeks to prove ability comes from environment, not genetics — her existence refutes it), and admires Ayanokōji from afar; resolved not to devote her life to the facility&#x27;s ideals; hints she has aligned with people she&#x27;s known much longer (not Ayanokōji), despite admiring him.<span class=\"pg\">p.5–7<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She idolizes him but says fate prevents her from taking his side.<span class=\"pg\">p.6–7<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p8-1\">→ After: Amasawa confronts Ayanokōji in the storm; reveals she is the White Room student<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4-p8-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa amasawa-ichika","q":"amasawa ichika amasawa confronts ayanokoji in the storm  reveals she is the white room student appears behind ayanokoji and nanase in the rain  red hair swaying  holding a whittled wooden stick   having tracked them  same table or gps relay   seems it s gonna really start coming down  huh sen pai   oh  nanase chan  shouldn t you be happy to see me  how aw fully cold you are to a dear companion from your very own group   i m super duper cute   ahaha  so i was seen after all   i can swear it  sure  but it doesn t really matter whether i keep my word or not  right   ding ding ding  correct  whether intentionally done or not  a broken watch is a broken watch   well there s no way i could do that  it has to do with the white room  after all   it s cuz i wanted to tell you that i m not your enemy  senpai   they chose the wrong person  they didn t predict that i was but a young maiden who secretly idolized you   you ve gotta talk with them and meet face to face before your admiration starts to feel justified  dismisses the idea that anyone else in her generation would have been won over   she alone idolized him   so please  don t go and get yourself crushed without my permission  okay  playful  evasive and theatrical  tosses the stick down as a  good faith  show  admits to watching them but not to pushing komiya kinoshita  reveals white room only knowledge to prove her identity  his childhood curricula  the pure white facility  and claims she intends to admire him  not destroy him   her true allegiance and motive remain ambiguous  brushes his cheek and departs with a cryptic warning  reveals herself as the white room student  claims to admire him and not be his enemy  spars with her  who accuses her of the cliff attack  calls her an  outsider  and a  loyal dog","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4-p8-1\"><h3><span class=\"ttl\">Amasawa confronts Ayanokōji in the storm; reveals she is the White Room student<\/span><span class=\"meta\">Y2V4 · p.8–21<\/span><\/h3><p class=\"setup\">Appears behind Ayanokōji and Nanase in the rain, red hair swaying, holding a whittled wooden stick — having tracked them (same Table or GPS relay).<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Seems it&#x27;s gonna really start coming down, huh Sen~pai?&quot;<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\">&quot;Oh? Nanase-chan, shouldn&#x27;t you be happy to see me? How aw~fully cold you are to a dear companion from your very own group.&quot;<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m super-duper cute~!&quot;<span class=\"pg\">p.9<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Ahaha, so I was seen after all.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I can swear it, sure, but it doesn&#x27;t really matter whether I keep my word or not, right?&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ding ding ding~ Correct~! Whether intentionally done or not, a broken watch is a broken watch.&quot;<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Well there&#x27;s no way I could do that. It has to do with the White Room, after all~&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s cuz I wanted to tell you that I&#x27;m not your enemy, Senpai.&quot;<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;they chose the wrong person. They didn&#x27;t predict that I was but a young maiden who secretly idolized you.&quot;<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;ve gotta talk with them and meet face-to-face before your admiration starts to feel justified.&quot;<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Dismisses the idea that anyone else in her generation would have been won over — she alone idolized him.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So please, don&#x27;t go and get yourself crushed without my permission, okay?&quot;<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful, evasive and theatrical (tosses the stick down as a &quot;good faith&quot; show), admits to watching them but not to pushing Komiya/Kinoshita; reveals White Room-only knowledge to prove her identity (his childhood curricula, the pure-white facility) and claims she intends to admire him, not destroy him — her true allegiance and motive remain ambiguous; brushes his cheek and departs with a cryptic warning.<span class=\"pg\">p.8–21<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reveals herself as the White Room student, claims to admire him and not be his enemy.<span class=\"pg\">p.8–21<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Spars with her, who accuses her of the cliff attack; calls her an &quot;outsider&quot; and a &quot;loyal dog.&quot;<span class=\"pg\">p.9–16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v4-p5-1\">← Before: Prologue: Amasawa&#x27;s monologue on the White Room<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v4_5-p10-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"amasawa-ichika","q":"amasawa ichika amasawa ichika mentioned in passing named in this volume  passing mentions on pages  p 30  p 89 91  p 93 95  p 138  p 140 141  passing mention only","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v4_5-p10-1\"><h3><span class=\"ttl\">amasawa-ichika mentioned in passing<\/span><span class=\"meta\">Y2V4.5 · p.10-290<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.30, p.89-91, p.93-95, p.138, p.140-141.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.10<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v5-p7-1","v":"y2v5","y":2,"o":21,"k":"","w":"amasawa-ichika","q":"amasawa ichika amasawa ichika mentioned in passing named in this volume  passing mentions on pages  p 74  passing mention only","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v5-p7-1\"><h3><span class=\"ttl\">amasawa-ichika mentioned in passing<\/span><span class=\"meta\">Y2V5 · p.7-243<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.74.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.7<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v6-p339-1","v":"y2v6","y":2,"o":22,"k":"narration","w":"ayanokouji-kiyotaka yagami-takuya amasawa-ichika","q":"amasawa ichika short story   the truth is  i ve always    amasawa checks his room from her own pov  enters ayanokoji s room  while he s sitting out  to check whether it s wiretapped   but her true goal is to see him   they should just ignore me and enjoy their school life  i highly recommend it   drawn in by my underwear  how pervy    teasing him while showing off  the truth is  i want to be by his side  playful  obsessive and possessive   tries to provoke him  showing her underwear  offering to expose the white room students so they ll fight  but he never bites  he only reads her moves  she admits she wants to be by his side even as a  nuisance  but knows her school life may not last forever  she idolizes him   wants to be close to him  he sees her as untrustworthy and won t take her information  she wants to expose  takuya  so he ll fight ayanokoji","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v6-p339-1\"><h3><span class=\"ttl\">Short story: &quot;The Truth is, I&#x27;ve Always…&quot; — Amasawa checks his room<\/span><span class=\"meta\">Y2V6 · p.339–341<\/span><\/h3><p class=\"setup\">From her own POV, enters Ayanokōji&#x27;s room (while he&#x27;s sitting out) to check whether it&#x27;s wiretapped — but her true goal is to see him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;They should just ignore me and enjoy their school life. I highly recommend it.&quot;<span class=\"pg\">p.339<\/span><\/li><li class=\"q narration\">&quot;Drawn in by my underwear? How pervy.&quot; — teasing him while showing off<span class=\"pg\">p.340<\/span><\/li><li class=\"q narration\">&quot;The truth is, I want to be by his side.&quot;<span class=\"pg\">p.340<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Playful, obsessive and possessive — tries to provoke him (showing her underwear, offering to expose the White Room students so they&#x27;ll fight), but he never bites (he only reads her moves); she admits she wants to be by his side even as a &quot;nuisance,&quot; but knows her school life may not last forever.<span class=\"pg\">p.339–341<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She idolizes him — wants to be close to him; he sees her as untrustworthy and won&#x27;t take her information.<span class=\"pg\">p.339–341<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> She wants to expose &quot;Takuya&quot; so he&#x27;ll fight Ayanokōji.<span class=\"pg\">p.339<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v7-p7-1","v":"y2v7","y":2,"o":23,"k":"","w":"amasawa-ichika","q":"amasawa ichika amasawa ichika mentioned in passing named in this volume  passing mentions on pages  p 104  p 108  p 126 130  p 161  p 168  passing mention only","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v7-p7-1\"><h3><span class=\"ttl\">amasawa-ichika mentioned in passing<\/span><span class=\"meta\">Y2V7 · p.7-207<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.104, p.108, p.126-130, p.161, p.168.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.7<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v8-p11-1","v":"y2v8","y":2,"o":24,"k":"","w":"amasawa-ichika","q":"amasawa ichika amasawa ichika mentioned in passing named in this volume  passing mentions on pages  p 28 36  p 38  p 53  p 59 61  p 107  passing mention only","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v8-p11-1\"><h3><span class=\"ttl\">amasawa-ichika mentioned in passing<\/span><span class=\"meta\">Y2V8 · p.11-208<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.28-36, p.38, p.53, p.59-61, p.107.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v9-p60-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"kushida-kikyou horikita-suzune ishigami-kyo-1a amasawa-ichika","q":"amasawa ichika amasawa  trailing the council recruitment  teasing kushida she tags along as horikita recruits the first year ishigami  while waiting she explains to ayanokoji that she came to see how kushida was doing after their contact at the festival   to be honest  i came to see how kushida senpai was doing  you know  we had a little bit of forced contact at the festival  so i was just wondering how things were going   i m the only one who can tease kushida senpai so blatantly  i wanted to check how mentally strong she is   simple curiosity  she admits she had considered joining the council but sees no point now  ayanokoji ties this to yagami s expulsion and her earlier hint about retracting her vow of no trouble  playful and calculating   openly enjoys needling kushida  follows the recruitment out of curiosity about the new president  and drops loaded hints about her intentions toward ayanokoji  teases her bluntly to gauge her mental strength after the festival  observes the new president closely  calls her serious  interesting and unique  her class a classmate  identifies him as the class s strategist","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v9-p60-1\"><h3><span class=\"ttl\">Amasawa: trailing the council recruitment, teasing Kushida<\/span><span class=\"meta\">Y2V9 · p.60–67<\/span><\/h3><p class=\"setup\">She tags along as Horikita recruits the first-year Ishigami; while waiting she explains to Ayanokōji that she came to see how Kushida was doing after their contact at the festival. She admits she had considered joining the council but sees no point now; Ayanokōji ties this to Yagami&#x27;s expulsion and her earlier hint about retracting her vow of no trouble.<\/p><p class=\"with\">with <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ishigami-kyo-1a.html\">Ishigami Kyō (Class 1-A)<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;To be honest, I came to see how Kushida-senpai was doing. You know, we had a little bit of forced contact at the festival, so I was just wondering how things were going.&quot;<span class=\"pg\">p.60<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m the only one who can tease Kushida-senpai so blatantly. I wanted to check how mentally strong she is.&quot;<span class=\"pg\">p.60<\/span><\/li><li class=\"q spoken\">&quot;Simple curiosity.&quot;<span class=\"pg\">p.61<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Playful and calculating — openly enjoys needling Kushida, follows the recruitment out of curiosity about the new president, and drops loaded hints about her intentions toward Ayanokōji.<span class=\"pg\">p.60–67<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Teases her bluntly to gauge her mental strength after the festival.<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Observes the new president closely, calls her serious, interesting and unique.<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishigami Kyō (Class 1-A)<\/b> Her Class A classmate; identifies him as the class&#x27;s strategist.<span class=\"pg\">p.61<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v9_5-p218-1","v":"y2v9.5","y":2,"o":26,"k":"","w":"amasawa-ichika","q":"amasawa ichika amasawa mentioned in passing named in this volume  passing mention  locator pages  p 218  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v9_5-p218-1\"><h3><span class=\"ttl\">Amasawa mentioned in passing<\/span><span class=\"meta\">Y2V9.5 · p.218<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.218; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.218<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p40-1","v":"y2v11","y":2,"o":30,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 2  the stacked group printout the organization chart lists her in nagumo s stacked group    class a takahashi osamu  toudou rin  amasawa ichika    printed in the bus printout  first years of class a  named in the printout  not present on these pages","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p40-1\"><h3><span class=\"ttl\">Ch.2: The stacked group printout<\/span><span class=\"meta\">Y2V11 · p.40<\/span><\/h3><p class=\"setup\">The organization chart lists her in Nagumo&#x27;s stacked group.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “• Class A Takahashi Osamu, Toudou Rin, Amasawa Ichika” — printed in the bus printout; first-years of Class A.<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in the printout; not present on these pages.<span class=\"pg\">p.40<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p62-1\">→ After: Ch.2: She promotes herself<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p62-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"nagumo-miyabi ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika ch 2  she promotes herself just before the group disbands  amasawa appears down the hallway  impatient  pretending she wasn t waiting  kiyotaka and nagumo are caught off guard   ah  finally you re out  you re done talking  right   that s why i promoted myself  i promised to contribute to getting first place   eh  it is  look  if i m aiming for nagumo senpai  she s my rival   but you told me to wait because you had important things to discuss with ayanokoji senpai  but you kept asahina senpai by your side  right  that s special  isn t it   we were told in advance what kind of exchange meeting would be held   eh  isn t it simply because the chances of winning seem high  after all  he was the student council president  i m a girl of age  so i want private points   i thought you and nagumo senpai would be competing soon  i thought it might be nice to be on your side and support you  but that wouldn t be fun  would it   we    yagami and tsukishiro management  sound familiar   the same network that runs her  kiyotaka notes the contradiction  she knows nagumo s three losses rule from him first  she stayed away from the discussion  her real aim is to be near him  she strong arms onto his group  he flinches  she courts his attention openly  she reveals to him alone the advance notice  she smells the match before it starts","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p62-1\"><h3><span class=\"ttl\">Ch.2: She promotes herself<\/span><span class=\"meta\">Y2V11 · p.62–66<\/span><\/h3><p class=\"setup\">Just before the group disbands, Amasawa appears down the hallway, impatient, pretending she wasn&#x27;t waiting; Kiyotaka and Nagumo are caught off guard.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ah, finally you&#x27;re out. You&#x27;re done talking, right?”<span class=\"pg\">p.62<\/span><\/li><li class=\"q spoken\">“That&#x27;s why I promoted myself. I promised to contribute to getting first place.”<span class=\"pg\">p.64<\/span><\/li><li class=\"q spoken\">“Eh~ it is. Look, if I&#x27;m aiming for Nagumo-senpai, she&#x27;s my rival.”<span class=\"pg\">p.64<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “But you told me to wait because you had important things to discuss with Ayanokōji-senpai, but you kept Asahina-senpai by your side, right? That&#x27;s special, isn&#x27;t it?”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We were told in advance what kind of exchange meeting would be held.”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? Isn&#x27;t it simply because the chances of winning seem high? After all, he was the student council president. I&#x27;m a girl of age, so I want private points.”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought you and Nagumo-senpai would be competing soon. I thought it might be nice to be on your side and support you, but that wouldn&#x27;t be fun, would it?”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> &quot;We&quot; = Yagami and Tsukishiro management; sound familiar — the same network that runs her; Kiyotaka notes the contradiction.<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She knows Nagumo&#x27;s three-losses rule from him first; she stayed away from the discussion; her real aim is to be near him.<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> She strong-arms onto his group; he flinches; she courts his attention openly.<span class=\"pg\">p.62–66<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She reveals to him alone the advance notice; she smells the match before it starts.<span class=\"pg\">p.62–66<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p40-1\">← Before: Ch.2: The stacked group printout<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p92-1\">→ After: Ch.3–4: The debt and the circle test<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p92-1","v":"y2v11","y":2,"o":30,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 3 4  the debt and the circle test the rematch conversation  amasawa s name recurs through horikita s request and the circle test   did you know how good her physical abilities are  it seems that she s also quite skilled in martial arts    horikita names her as the rematch opponent  kiyotaka already knows   setting martial arts aside  i do regularly check the oaa and have a rough grasp of it    kiyotaka s knowledge of amasawa   i don t like it either  but from the way you talk  it seems you know exactly how strong amasawa san is  don t you    horikita s probe  amasawa is his benchmark for every fighter he tutors   i ve been learning martial arts since i was little  that s all there is to it    kiyotaka s explanation for his own strength  he compares the two   if we talk about physical ability  if we treat you two as equals and give you a score of 50  then amasawa would be 60  so a difference of about 10    the printed estimate   i ll definitely make you use both hands tomorrow    ibuki s resolve to force the fight  named throughout  not present on these pages","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p92-1\"><h3><span class=\"ttl\">Ch.3–4: The debt and the circle test<\/span><span class=\"meta\">Y2V11 · p.92–107<\/span><\/h3><p class=\"setup\">The rematch conversation; Amasawa&#x27;s name recurs through Horikita&#x27;s request and the circle test.<\/p><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Did you know how good her physical abilities are? It seems that she’s also quite skilled in martial arts.” — Horikita names her as the rematch opponent; Kiyotaka already knows.<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Setting martial arts aside, I do regularly check the OAA and have a rough grasp of it.” — Kiyotaka&#x27;s knowledge of Amasawa.<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I don&#x27;t like it either. But from the way you talk, it seems you know exactly how strong Amasawa-san is, don&#x27;t you?” — Horikita&#x27;s probe; Amasawa is his benchmark for every fighter he tutors.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I&#x27;ve been learning martial arts since I was little. That&#x27;s all there is to it.” — Kiyotaka&#x27;s explanation for his own strength; he compares the two.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “If we talk about physical ability, if we treat you two as equals and give you a score of 50, then Amasawa would be 60, so a difference of about 10.” — the printed estimate.<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I&#x27;ll definitely make you use both hands tomorrow.” — Ibuki&#x27;s resolve to force the fight.<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named throughout; not present on these pages.<span class=\"pg\">p.92–107<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p62-1\">← Before: Ch.2: She promotes herself<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p112-1\">→ After: Ch.4: The sunshine taunt<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p112-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"sakayanagi-arisu kitou-hayato amasawa-ichika","q":"amasawa ichika ch 4  the sunshine taunt she slides into the sakayanagi ayanokoji exchange  she taunts the princess about losing three times  kito grabs her wrist   good morning   being energetic is one of my strengths  you know   it seems like ayanokoji senpai has been winning all along  but  you lost three times on the first day  arisu senpai  i m worried that you might be in a pinch already   hmm  so if you lose  it can t be helped  i was hoping for a little bit of interaction with other years this time  as it s a valuable opportunity   you re bluffing  i ve heard that you lost in the previous special exam and ended up at the bottom   what are you doing  kito senpai  isn t this something you should do to ryuen senpai or someone   you re like a knight protecting a princess  but it s interesting  i don t mind even if you re violent against a girl  maybe i went too far with my joke   i ll play with you again next time  please be ready to give it your all  arisu senpai  she has done her homework on the second years  she prods sakayanagi  kito doesn t loosen his grip  she backs off  she teases her about the hidden command situation  sakayanagi stays cool  he restrains her wrist  she flirts with the danger","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p112-1\"><h3><span class=\"ttl\">Ch.4: The sunshine taunt<\/span><span class=\"meta\">Y2V11 · p.112–113<\/span><\/h3><p class=\"setup\">She slides into the Sakayanagi–Ayanokōji exchange; she taunts the princess about losing three times; Kitō grabs her wrist.<\/p><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Good morning!”<span class=\"pg\">p.112<\/span><\/li><li class=\"q spoken\">“Being energetic is one of my strengths, you know.”<span class=\"pg\">p.112<\/span><\/li><li class=\"q spoken\">“It seems like Ayanokōji-senpai has been winning all along, but... you lost three times on the first day, Arisu-senpai. I&#x27;m worried that you might be in a pinch already.”<span class=\"pg\">p.112<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Hmm? So if you lose, it can&#x27;t be helped? I was hoping for a little bit of interaction with other years this time, as it&#x27;s a valuable opportunity.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You&#x27;re bluffing. I&#x27;ve heard that you lost in the previous special exam and ended up at the bottom.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you doing, Kitō-senpai? Isn&#x27;t this something you should do to Ryūen-senpai or someone?”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You&#x27;re like a knight protecting a princess, but it&#x27;s interesting. I don&#x27;t mind even if you&#x27;re violent against a girl... Maybe I went too far with my joke.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll play with you again next time. Please be ready to give it your all, Arisu-senpai!”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She has done her homework on the second-years; she prods Sakayanagi; Kitō doesn&#x27;t loosen his grip; she backs off.<span class=\"pg\">p.112–113<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> She teases her about the hidden command situation; Sakayanagi stays cool.<span class=\"pg\">p.112–113<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> He restrains her wrist; she flirts with the danger.<span class=\"pg\">p.112–113<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p92-1\">← Before: Ch.3–4: The debt and the circle test<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p145-1\">→ After: Ch.6: The blindfold and the special training<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p145-1","v":"y2v11","y":2,"o":30,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 6  the blindfold and the special training the third day  the blindfold demand  the amasawa rematch looms   i have to kick you at least once  or i ll be frustrated    ibuki s motivation  the amasawa rematch is the horizon   the main reason you chose the last day was to manage the risk of injury  wasn t it    horikita s deduction   this may have been the reason why she asked me to help her to take revenge on amasawa    kiyotaka s read of ibuki s vengeful streak  named throughout  not present on these pages","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p145-1\"><h3><span class=\"ttl\">Ch.6: The blindfold and the special training<\/span><span class=\"meta\">Y2V11 · p.145–151<\/span><\/h3><p class=\"setup\">The third day; the blindfold demand; the Amasawa rematch looms.<\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “I have to kick you at least once, or I&#x27;ll be frustrated.” — Ibuki&#x27;s motivation; the Amasawa rematch is the horizon.<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “The main reason you chose the last day was to manage the risk of injury, wasn&#x27;t it?” — Horikita&#x27;s deduction.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “This may have been the reason why she asked me to help her to take revenge on Amasawa.” — Kiyotaka&#x27;s read of Ibuki&#x27;s vengeful streak.<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named throughout; not present on these pages.<span class=\"pg\">p.145–151<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p112-1\">← Before: Ch.4: The sunshine taunt<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p159-1\">→ After: Ch.6: Fifty-seven points<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p159-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika ch 6  fifty seven points the 17th match  she draws the amasawa line  she fires  the scoreboard reads 9  9  10  9  10  10   no way  her 57 is the match s peak  katsuragi at 37  the instructors are surprised along with the students   you re amazing  senpai  it s frustrating  but i lost  didn t i   i was trying to put pressure on you  but it didn t work  did it   you hadn t practiced archery other than yesterday s game  right  he watched tutorials in the middle of the night  nagumo may be irritated  she applauds him despite losing by a single point","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p159-1\"><h3><span class=\"ttl\">Ch.6: Fifty-seven points<\/span><span class=\"meta\">Y2V11 · p.159–161<\/span><\/h3><p class=\"setup\">The 17th match; she draws the Amasawa line; she fires; the scoreboard reads 9, 9, 10, 9, 10, 10.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“No way...”<span class=\"pg\">p.160<\/span><\/li><li class=\"q spoken\">“You&#x27;re amazing, Senpai. It&#x27;s frustrating, but I lost, didn&#x27;t I?”<span class=\"pg\">p.161<\/span><\/li><li class=\"q spoken\">“I was trying to put pressure on you, but it didn&#x27;t work, did it?”<span class=\"pg\">p.161<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Her 57 is the match&#x27;s peak; Katsuragi at 37; the instructors are surprised along with the students.<span class=\"pg\">p.160<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You hadn&#x27;t practiced archery other than yesterday&#x27;s game, right?”<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He watched tutorials in the middle of the night; Nagumo may be irritated; she applauds him despite losing by a single point.<span class=\"pg\">p.161<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p145-1\">← Before: Ch.6: The blindfold and the special training<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p162-1\">→ After: Ch.6: “your most skillful player”<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p162-1","v":"y2v11","y":2,"o":30,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 6   your most skillful player  the final debrief  nagumo compliments her  nagumo   your most skillful player  amasawa  had a great performance though  she hits her targets quite gracefully    quoted by kiyotaka in the debrief  she does not appear in person on these pages  named as the strongest member of nagumo s group  not present on these pages","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p162-1\"><h3><span class=\"ttl\">Ch.6: “your most skillful player”<\/span><span class=\"meta\">Y2V11 · p.162<\/span><\/h3><p class=\"setup\">The final debrief; Nagumo compliments her.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Nagumo: “Your most skillful player, Amasawa, had a great performance though. She hits her targets quite gracefully.” — quoted by Kiyotaka in the debrief; she does not appear in person on these pages.<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named as the strongest member of Nagumo&#x27;s group; not present on these pages.<span class=\"pg\">p.162<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p159-1\">← Before: Ch.6: Fifty-seven points<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p177-1\">→ After: Ch.7: The personal vendetta<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p177-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"nagumo-miyabi yagami-takuya karuizawa-kei horikita-manabu amasawa-ichika","q":"amasawa ichika ch 7  the personal vendetta past 11 p m  the previous day  nagumo walks down the darkened hallway alone  she is waiting in the darkened cafeteria  he walks in with his hands in his pockets   you came as promised   i ve never refused a woman s call before   yawn  what a cheesy line  honestly  i hate your type   relax  i m not into women like you either   so  there was no need to threaten me  that might ve been an unnecessary move   amasawa  did you really want to be alone with me that much   opportunities to be alone with a former student council president don t come around often  do they   i want to confirm something  what would you have done if i hadn t come   i would ve beaten up your precious asahina senpai  nagumo senpai   did you show your skills in archery with ayanokoji to make your threats more effective   well  yeah  if i don t show that i m capable  people might dismiss a woman s threats   okay  let s get to the point  so  why did you threaten me to call me out   there s a problem that only you can solve  nagumo senpai  that s what i want to talk about   you had plenty of chances to talk during the exchange meeting   by the way  i m thinking of seriously injuring you  nagumo senpai   seriously injuring me  that s quite sudden   is it too unrealistic  or do you think you can t lose to a girl   i wonder  maybe it s both   will you run away   can i at least hear the reason   the reason  hmm  let s just say it s a personal vendetta   personal vendetta  huh   yes  a personal vendetta  now  if we take too long  the teachers might find us  and it would be embarrassing if the fact that you were beaten by a girl got out  so can we start   just to confirm  do you really think you can beat me   haha  i ve been waiting for you to say that  let s give it a try   it s easy to say  but there s nothing in it for me  it would be a problem if i retaliated against a girl who came at me out of personal vendetta   it s pointless to resist anyway  you can just let me beat you up  that way  you ll lose your pride  but you won t get penalized by the school  i recommend it   aren t you afraid of being expelled   of course not  if i get expelled  i have nothing to lose   so  persuasion is impossible   yes  i have no  value  in other words  i m invincible   did you get cautious because of the recording  go ahead and answer without holding back  state the reasons behind this so called personal vendetta   you teamed up with ayanokoji senpai and expelled yagami takuya  right  it s payback   yagami  don t tell me  you were yagami s girlfriend   that s not it  but we were like siblings who had surpassed that kind of relationship   then aren t you targeting the wrong person  i wasn t the one who led that   i know that  i told you  this is just a personal vendetta  unfortunately  even if i stand on my head  i can t beat ayanokoji senpai  and i thought about beating up karuizawa senpai and expelling her  but that s a bit scary   scary  of getting revenge from ayanokoji  i don t think he cares about what happens to karuizawa   ayanokoji senpai has his own goals  i don t want to interfere with that   people like nagumo senpai are well suited for stories where the character ultimately faces their downfall at the conclusion   it suits me  huh   last year and the year before  the one always causing a stir at this school was horikita manabu   this year it s ayanokoji   i m sure it ll be the same next year after i m gone   i was indeed enrolled at this school for three years   even if i attracted attention within my year  it didn t resonate at all with the upper or lower years  a page break falls inside her speech across these lines  the phrase completes on the next page  the content is unaffected   i realized it just before graduation  it s not horikita senpai or ayanokoji that s to blame  it s me who couldn t reach that realm   but  that s not the case  i wouldn t have been satisfied with that situation either   that s why i won t quit this game  next year i ll do it again with horikita senpai  and someday i ll have a real match with ayanokoji and settle it   before you put anything into action  i have a gift for you   a gift  i m the type to throw away presents from men i m not interested in without opening them   i see  then it might end with you throwing it away without opening it  after all  it s just a message from ayanokoji   ayanokoji senpai   if it s a lie to save yourself  it will only widen the wound   believe my words or not  it s up to you  the message from ayanokoji is  you still have value  don t waste it  she lays everything bare  the summons  the threat  yagami s expulsion  the vendetta  the gift she can t refuse  the message foresees her  she targets him as a revenge punching bag  he hands her the one line that disarms her  she is left speechless in the dark   you were yagami s girlfriend    no  they were like siblings who had surpassed that kind of relationship  she floats beating up karuizawa senpai and expelling her  she drops it out of consideration for ayanokoji s goals  she names manabu as the always causing a stir figure of the two years before","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p177-1\"><h3><span class=\"ttl\">Ch.7: The personal vendetta<\/span><span class=\"meta\">Y2V11 · p.177–181<\/span><\/h3><p class=\"setup\">Past 11 p.m. the previous day; Nagumo walks down the darkened hallway alone; she is waiting in the darkened cafeteria; he walks in with his hands in his pockets.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You came as promised.”<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “I&#x27;ve never refused a woman&#x27;s call before,”<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\">“Yawn, what a cheesy line. Honestly, I hate your type.”<span class=\"pg\">p.177<\/span><\/li><\/ul><details class=\"more\"><summary>58 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Relax. I&#x27;m not into women like you either.”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, there was no need to threaten me. That might&#x27;ve been an unnecessary move.”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Amasawa, did you really want to be alone with me that much?”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Opportunities to be alone with a former student council president don&#x27;t come around often, do they?”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want to confirm something. What would you have done if I hadn&#x27;t come?”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would&#x27;ve beaten up your precious Asahina-senpai, Nagumo-senpai.”<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you show your skills in archery with Ayanokōji to make your threats more effective?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, yeah. If I don&#x27;t show that I&#x27;m capable, people might dismiss a woman&#x27;s threats.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Okay, let&#x27;s get to the point. So, why did you threaten me to call me out?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There&#x27;s a problem that only you can solve, Nagumo-senpai. That&#x27;s what I want to talk about.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You had plenty of chances to talk during the exchange meeting.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “By the way, I&#x27;m thinking of seriously injuring you, Nagumo-senpai.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Seriously injuring me? That&#x27;s quite sudden.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is it too unrealistic? Or do you think you can&#x27;t lose to a girl?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wonder. Maybe it&#x27;s both.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Will you run away?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can I at least hear the reason?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The reason? Hmm, let&#x27;s just say it&#x27;s a personal vendetta.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Personal vendetta, huh?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, a personal vendetta. Now, if we take too long, the teachers might find us, and it would be embarrassing if the fact that you were beaten by a girl got out, so can we start?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just to confirm, do you really think you can beat me?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Haha, I&#x27;ve been waiting for you to say that. Let&#x27;s give it a try.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s easy to say, but there&#x27;s nothing in it for me. It would be a problem if I retaliated against a girl who came at me out of personal vendetta.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s pointless to resist anyway, you can just let me beat you up. That way, you&#x27;ll lose your pride, but you won&#x27;t get penalized by the school. I recommend it.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Aren&#x27;t you afraid of being expelled?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course not. If I get expelled, I have nothing to lose.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, persuasion is impossible?”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, I have no &#x27;value.&#x27; In other words, I&#x27;m invincible.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you get cautious because of the recording? Go ahead and answer without holding back. State the reasons behind this so-called personal vendetta.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You teamed up with Ayanokōji-senpai and expelled Yagami Takuya, right? It&#x27;s payback.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yagami? Don&#x27;t tell me, you were Yagami&#x27;s girlfriend?”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not it, but we were like siblings who had surpassed that kind of relationship.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then aren&#x27;t you targeting the wrong person? I wasn&#x27;t the one who led that.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know that. I told you, this is just a personal vendetta. Unfortunately, even if I stand on my head, I can&#x27;t beat Ayanokōji-senpai, and I thought about beating up Karuizawa-senpai and expelling her, but that&#x27;s a bit scary.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Scary? Of getting revenge from Ayanokōji? I don&#x27;t think he cares about what happens to Karuizawa.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-senpai has his own goals. I don&#x27;t want to interfere with that.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “People like Nagumo-senpai are well-suited for stories where the character ultimately faces their downfall at the conclusion.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It suits me, huh?”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Last year and the year before, the one always causing a stir at this school was Horikita Manabu.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This year it&#x27;s Ayanokōji.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sure it&#x27;ll be the same next year after I&#x27;m gone.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I was indeed enrolled at this school for three years.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if I attracted attention within my year, it didn&#x27;t resonate at all with the upper or lower years.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> A page break falls inside her speech across these lines; the phrase completes on the next page; the content is unaffected.<span class=\"pg\">p.179–180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I realized it just before graduation. It&#x27;s not Horikita-senpai or Ayanokōji that&#x27;s to blame. It&#x27;s me who couldn&#x27;t reach that realm.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But… that&#x27;s not the case. I wouldn&#x27;t have been satisfied with that situation either.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s why I won&#x27;t quit this game. Next year I&#x27;ll do it again with Horikita-senpai. And someday I&#x27;ll have a real match with Ayanokōji and settle it.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Before you put anything into action, I have a gift for you.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A gift? I&#x27;m the type to throw away presents from men I&#x27;m not interested in without opening them.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. Then it might end with you throwing it away without opening it. After all, it&#x27;s just a message from Ayanokōji.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...Ayanokōji-senpai...?”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it&#x27;s a lie to save yourself, it will only widen the wound.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Believe my words or not, it&#x27;s up to you. The message from Ayanokōji is &#x27;You still have value. Don&#x27;t waste it.&#x27;”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She lays everything bare: the summons, the threat, Yagami&#x27;s expulsion, the vendetta; the gift she can&#x27;t refuse; the message foresees her.<span class=\"pg\">p.177–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> She targets him as a revenge punching bag; he hands her the one line that disarms her; she is left speechless in the dark.<span class=\"pg\">p.177–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> “You were Yagami&#x27;s girlfriend?” — no; they were like siblings who had surpassed that kind of relationship.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> She floats beating up Karuizawa-senpai and expelling her; she drops it out of consideration for Ayanokōji&#x27;s goals.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> She names Manabu as the always-causing-a-stir figure of the two years before.<span class=\"pg\">p.179–180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p162-1\">← Before: Ch.6: “your most skillful player”<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p182-1\">→ After: Ch.8–Epilogue: The morning of the fight<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v11-p182-1","v":"y2v11","y":2,"o":30,"k":"","w":"amasawa-ichika","q":"amasawa ichika ch 8 epilogue  the morning of the fight the morning everything ends  the rematch is set for 7 o clock before breakfast   the fight with amasawa was set before breakfast  at 7 o clock    the only announcement  the fight itself is never narrated   it s good that you re motivated    the stakes settled before the fight   even with the amasawa san situation  you didn t look displeased even once    horikita s observation   she s really strong  isn t she  even if we fought two against one  we still couldn t win in the end    the postmortem   it looked like amasawa san noticed your influence right after the fight started  but she seemed very happy  what s your relationship with her    horikita s probe  named throughout  present only in the off page rematch  the fight itself is never narrated","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v11-p182-1\"><h3><span class=\"ttl\">Ch.8–Epilogue: The morning of the fight<\/span><span class=\"meta\">Y2V11 · p.182–198<\/span><\/h3><p class=\"setup\">The morning Everything ends; the rematch is set for 7 o&#x27;clock before breakfast.<\/p><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “The fight with Amasawa was set before breakfast, at 7 o&#x27;clock.” — the only announcement; the fight itself is never narrated.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “It&#x27;s good that you&#x27;re motivated.” — the stakes settled before the fight.<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Even with the Amasawa-san situation, you didn&#x27;t look displeased even once.” — Horikita&#x27;s observation.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “She&#x27;s really strong, isn&#x27;t she? Even if we fought two against one, we still couldn&#x27;t win in the end.” — the postmortem.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “it looked like Amasawa-san noticed your influence right after the fight started. But she seemed very happy. What&#x27;s your relationship with her?” — Horikita&#x27;s probe.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named throughout; present only in the off-page rematch; the fight itself is never narrated.<span class=\"pg\">p.182–198<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amasawa-ichika-y2v11-p177-1\">← Before: Ch.7: The personal vendetta<\/button><\/div><\/article>"},{"i":"sc-amasawa-ichika-y2v12-p38-1","v":"y2v12","y":2,"o":31,"k":"spoken","w":"nanase-tsubasa hasebe-haruka nagumo-miyabi amasawa-ichika","q":"amasawa ichika ch 2  the nagumo report and the nanase assignment friday evening  the mall s edge  she runs up  crashing into hasebe s half finished attempt to speak with ayanokoji  and stays for her real purpose  a report   even though you have karuizawa senpai as your girlfriend  now you re plotting on making this busty one your girlfriend too   ah  i didn t come here to annoy you today  when i attacked nagumo senpai during the last camp  there was also a surprise counterattack  so i m here to report that  she lays out her own decision  she attacked nagumo at the last camp prepared to be expelled  she has reconsidered and will keep attending school for a while  she offers her spare time   i haven t come to a conclusion yet  he assigns her to look into nanase tsubasa   not to expel her  only to gather information on her real intentions  she salutes exaggeratedly and accepts  then mutters  thank you  senpai  as she leaves   do you want me to expel her   okay  understood   thank you  senpai  he assigns her to dig into nanase s real intentions  the assignment is intelligence gathering  not expulsion  she ran the interception  his loss   hasebe left unfinished  report  her surprise attack on him at the last camp met a counterattack  she survived and will keep attending school for now","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v12-p38-1\"><h3><span class=\"ttl\">Ch.2: The Nagumo report and the Nanase assignment<\/span><span class=\"meta\">Y2V12 · p.38–40<\/span><\/h3><p class=\"setup\">Friday evening, the mall&#x27;s edge; she runs up, crashing into Hasebe&#x27;s half-finished attempt to speak with Ayanokōji, and stays for her real purpose: a report. She lays out her own decision: she attacked Nagumo at the last camp prepared to be expelled; she has reconsidered and will keep attending school for a while; she offers her spare time. He assigns her to look into Nanase Tsubasa — not to expel her, only to gather information on her real intentions; she salutes exaggeratedly and accepts, then mutters &quot;...Thank you, Senpai.&quot; as she leaves.<\/p><p class=\"with\">with <a href=\"nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Even though you have Karuizawa-senpai as your girlfriend, now you’re plotting on making this busty one your girlfriend too?”<span class=\"pg\">p.39<\/span><\/li><li class=\"q spoken\">“Ah, I didn’t come here to annoy you today… When I attacked Nagumo-senpai during the last camp, there was also a surprise counterattack, so I’m here to report that.”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\">“I haven’t come to a conclusion yet.”<span class=\"pg\">p.40<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Do you want me to expel her?”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Okay, understood.”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Thank you, Senpai.”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> He assigns her to dig into Nanase&#x27;s real intentions; the assignment is intelligence-gathering, not expulsion.<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> She ran the interception; his loss — Hasebe left unfinished.<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Report: her surprise attack on him at the last camp met a counterattack; she survived and will keep attending school for now.<span class=\"pg\">p.40<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y2v12_5-p148-1","v":"y2v12.5","y":2,"o":32,"k":"","w":"ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika ch 9 mentioned appears in ch 9  appears in this volume","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y2v12_5-p148-1\"><h3><span class=\"ttl\">Ch.9<\/span><span class=\"meta\">Y2V12.5 · p.148-176<\/span><\/h3><p class=\"setup\">Mentioned/appears in Ch.9.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Appears in this volume.<span class=\"pg\">p.148-176<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amasawa-ichika-y3v1-p90-1","v":"y3v1","y":3,"o":33,"k":"spoken","w":"ichinose-honami ayanokouji-kiyotaka amasawa-ichika","q":"amasawa ichika amasawa probes ichinose about ayanokoji calls out to ichinose in keyaki mall  smiling innocently  brings up the gym and ayanokoji   did you go to the gym today   but i tend to spend a lot of money  so the monthly expense is kind of painful   it does matter  i like ayanokouji senpai a lot   oh  i mean i like him as a senpai  not that there are any romantic feelings   actually  i really do love him in that way   i m pretty sharp  you know   after all  you ve slept with ayanokouji senpai  right   you re saying you re that special cake  but you re dangerously full of yourself   hold on  did ayanokouji senpai really talk to you about the white room  ichinose senpai   shoot  i m the one getting carried away here  playful but venomous   feigns innocence then turns hostile  probing ichinose with a  bomb  question about sleeping with ayanokoji to see her agitation  is outmaneuvered when ichinose mentions the white room  stiffens  then realizes she was the one countered  probes her about her relationship with ayanokoji  ends up respecting her more  claims to love him  in that way  the reason she remains at the school is to make ayanokoji happy","h":"<article class=\"card\" id=\"sc-amasawa-ichika-y3v1-p90-1\"><h3><span class=\"ttl\">Amasawa probes Ichinose about Ayanokōji<\/span><span class=\"meta\">Y3V1 · p.90–97<\/span><\/h3><p class=\"setup\">Calls out to Ichinose in Keyaki Mall, smiling innocently; brings up the gym and Ayanokōji.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Did you go to the gym today?&quot;<span class=\"pg\">p.90<\/span><\/li><li class=\"q spoken\">&quot;But I tend to spend a lot of money, so the monthly expense is kind of painful.&quot;<span class=\"pg\">p.90<\/span><\/li><li class=\"q spoken\">&quot;It does matter. I like Ayanokouji-senpai a lot.&quot;<span class=\"pg\">p.90<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Oh, I mean I like him as a senpai, not that there are any romantic feelings~&quot;<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Actually, I really do love him in that way.&quot;<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m pretty sharp, you know.&quot;<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;After all… you&#x27;ve slept with Ayanokouji-senpai, right?&quot;<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re saying you&#x27;re that special cake, but you&#x27;re dangerously full of yourself.&quot;<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hold on. Did Ayanokouji-senpai really talk to you about the White Room, Ichinose-senpai?&quot;<span class=\"pg\">p.95<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;…Shoot. I&#x27;m the one getting carried away here.&quot;<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful but venomous — feigns innocence then turns hostile, probing Ichinose with a &quot;bomb&quot; question about sleeping with Ayanokōji to see her agitation; is outmaneuvered when Ichinose mentions the White Room, stiffens, then realizes she was the one countered.<span class=\"pg\">p.90–97<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Probes her about her relationship with Ayanokōji; ends up respecting her more.<span class=\"pg\">p.90–96<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Claims to love him &quot;in that way&quot;; the reason she remains at the school is to make Ayanokōji happy.<span class=\"pg\">p.90–97<\/span><\/li><\/ul><\/details><\/article>"}];
